SELECT DISTINCT project_id FROM ast_device WHERE tenant_id = #{query.tenantId} AND deleted = b'0' AND shipment_time IS NOT NULL AND sn IS NOT NULL AND TRIM(sn) <> ''
AND project_id IN #{projectId}
AND 1 = 0

SELECT id, sn, product_code, product_model

ORDER BY sn, id
LIMIT #{query.offset}, #{query.pageSize}
